function sanitizePlanId(planId) {
	if (planId === "essencial_mensal" || planId === "pro_anual") return planId;
	return "pro_mensal";
}
function sanitizeSubscriptionStatus(status) {
	if (status === "active" || status === "past_due" || status === "canceled") return status;
	return "trialing";
}
